.darma-loader-darma-b14-test-tube-bubble { --accent: var(--loader-color, #a855f7); --accent-2: var(--loader-secondary-color, #334155); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .92); position: relative; display: flex; justify-content: space-between; align-items: flex-end; padding: 0 6%; }
.darma-loader-darma-b14-test-tube-bubble::after { content: ''; position: absolute; z-index: 0; bottom: 9%; left: 2%; width: 96%; height: calc(var(--loader-size, 112px) * .075); border-radius: 3px; background: linear-gradient(color-mix(in srgb, #000 22%, var(--accent-2)), color-mix(in srgb, #000 46%, var(--accent-2))); }
.darma-loader-darma-b14-test-tube-bubble span { position: relative; z-index: 1; width: 16%; overflow: hidden; border-radius: 3px 3px 999px 999px; background: linear-gradient(90deg, rgba(255, 255, 255, .8) 0 22%, rgba(255, 255, 255, .3) 30%); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 20%, var(--accent-2)); }
.darma-loader-darma-b14-test-tube-bubble span::before { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; background: linear-gradient(90deg, color-mix(in srgb, #fff 42%, var(--accent)) 0 24%, var(--accent) 32%); animation: darma-loader-darma-b14-test-tube-bubble-level calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b14-test-tube-bubble span::after { content: ''; position: absolute; bottom: 8%; left: 28%; width: 44%; height: 13%; border-radius: 50%; background: rgba(255, 255, 255, .72); animation: darma-loader-darma-b14-test-tube-bubble-bubble-up calc(var(--loader-speed, 1s) * 1.5) ease-in infinite; }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(1) { height: 88%; }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(2) { height: 74%; }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(2)::before { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(2)::after { animation-delay: calc(var(--loader-speed, 1s) * .38); }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(3) { height: 94%; }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(3)::before { animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(3)::after { animation-delay: calc(var(--loader-speed, 1s) * .75); }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(4) { height: 68%; }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(4)::before { animation-delay: calc(var(--loader-speed, 1s) * .9); }
.darma-loader-darma-b14-test-tube-bubble span:nth-child(4)::after { animation-delay: calc(var(--loader-speed, 1s) * 1.12); }
@keyframes darma-loader-darma-b14-test-tube-bubble-level { 0%, 100% { height: 36%; } 50% { height: 68%; } }
@keyframes darma-loader-darma-b14-test-tube-bubble-bubble-up { 0% { opacity: 0; transform: translateY(0) scale(.5); } 20% { opacity: 1; } 100% { opacity: 0; transform: translateY(-260%) scale(1); } }

